import React, { useState } from "react";
import StudentRegister from "./StudentRegister";
import CompanyRegister from "./CompanyRegister";
import "../Styles/UserRegister.css";

const Register = () => {
  const [role, setRole] = useState("student");

  return (
    <div className="reg-page">
      <h1 className="reg-title">
        Create your <span className="accent">account</span>
      </h1>
      <p className="reg-sub">Choose your role to continue:</p>

      {/* Switch Buttons */}
      <div className="role-switch">
        <button
          className={role === "student" ? "role-btn active" : "role-btn"}
          onClick={() => setRole("student")}
        >
          Student
        </button>
        <button
          className={role === "company" ? "role-btn active" : "role-btn"}
          onClick={() => setRole("company")}
        >
          Company
        </button>
      </div>

      {/* Show Form Based on Selected Role */}
      {role === "student" ? <StudentRegister /> : <CompanyRegister />}
    </div>
  );
};

export default Register;
